#!/usr/bin/env python3
"""Merge overlay GIFs into a base tileset/palette generated by SDK gif2zeal.

Base tiles keep their original indices, with trailing flat padding removed.
Overlays share the base palette and tileset, each producing a .ztm map.
Palette index 0 stays transparent; overlay pixels use opaque RGB565 entries.
The final tileset uses the repo-specific LZ77 format.
"""

import argparse
import os
import sys
from pathlib import Path

from PIL import Image

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from tileset_lz77 import TS, lz77_compress

# The tileset lives in 64 KiB of VRAM as 256 byte tiles, so 256 tiles is the
# hard ceiling a merged tileset can reach, and a tilemap cell is one byte.
MAX_TILES = 256


def rgb565(r, g, b):
    """RGB888 -> RGB565. Green is the 6-bit field, so it shifts by 2."""
    return ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3)


def read_gif(path):
    img = Image.open(path)
    if img.mode != "P":
        sys.exit("%s is not a paletted GIF (mode %s)" % (path, img.mode))
    if img.size[1] % TS:
        sys.exit("%s height %d is not a multiple of %d" % (path, img.size[1], TS))
    if img.size[0] % TS:
        sys.exit("%s width %d is not a multiple of %d" % (path, img.size[0], TS))
    return img


def read_base(tileset, palette):
    """Read SDK raw 8bpp tiles and little-endian RGB565 palette entries."""
    data = Path(tileset).read_bytes()
    if len(data) % (TS * TS):
        sys.exit("%s is not a whole number of tiles" % tileset)
    cells = [tuple(data[i:i + TS * TS])
             for i in range(0, len(data), TS * TS)]
    while cells and all(p == cells[-1][0] for p in cells[-1]):
        cells.pop()
    if len(cells) > MAX_TILES:
        sys.exit("%s exceeds %d tiles" % (tileset, MAX_TILES))

    data = Path(palette).read_bytes()
    if len(data) % 2 or len(data) > 512:
        sys.exit("%s is not a valid RGB565 palette" % palette)
    entries = [data[i] | (data[i + 1] << 8) for i in range(0, len(data), 2)]
    entries.extend([0] * (256 - len(entries)))
    return cells, entries


def fit_colours(img, palette, next_free):
    """Maps the picture's own palette onto the shared palette.

    Returns the index to paint for every palette index the picture uses, and
    the next unclaimed slot. Index 0 is skipped so the transparent colour is
    never overwritten with an image colour.
    """
    pal = img.getpalette() or []
    px = img.load()
    width, height = img.size
    used = sorted({px[x, y] for y in range(height) for x in range(width)})
    mapping = {}

    for index in used:
        base = index * 3
        value = rgb565(pal[base], pal[base + 1], pal[base + 2])
        slot = None
        for i in range(1, 256):
            if palette[i] == value:
                slot = i
                break
        if slot is None:
            if next_free >= MAX_TILES:
                sys.exit("%s needs more palette slots than the palette holds"
                         % img.filename)
            slot = next_free
            palette[slot] = value
            next_free += 1
        mapping[index] = slot
    return mapping, next_free


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-tileset", required=True, help="SDK raw 8bpp tileset")
    ap.add_argument("--base-palette", required=True, help="SDK RGB565 palette")
    ap.add_argument("-t", "--tileset", required=True)
    ap.add_argument("-p", "--palette", required=True)
    ap.add_argument("-o", "--overlay", action="append", default=[],
                    help="picture to merge in; repeatable")
    ap.add_argument("-m", "--overlay-map", action="append", default=[],
                    help="tilemap to write for the matching --overlay")
    args = ap.parse_args()

    if len(args.overlay) != len(args.overlay_map):
        sys.exit("every --overlay needs its own --overlay-map")

    base, palette = read_base(args.base_tileset, args.base_palette)

    taken = {i for tile in base for i in tile}
    next_free = max(taken) + 1 if taken else 1

    known = {}
    for index, tile in enumerate(base):
        known.setdefault(tile, index)

    extra = []
    reports = []

    for path, out in zip(args.overlay, args.overlay_map):
        img = read_gif(path)
        mapping, next_free = fit_colours(img, palette, next_free)

        px = img.load()
        width, height = img.size
        cols, rows = width // TS, height // TS
        added = 0
        cells = []
        for ty in range(rows):
            for tx in range(cols):
                tile = tuple(
                    mapping[px[tx * TS + x, ty * TS + y]]
                    for y in range(TS) for x in range(TS)
                )
                if tile not in known:
                    if len(base) + len(extra) + 1 > MAX_TILES:
                        sys.exit("%s would push the tileset past %d tiles"
                                 % (img.filename, MAX_TILES))
                    known[tile] = len(base) + len(extra)
                    extra.append(tile)
                    added += 1
                cells.append(known[tile])

        with open(out, "wb") as f:
            f.write(bytes(cells))
        reports.append("%s -> %dx%d cells, %d tiles added, %d bytes in VRAM"
                       % (os.path.basename(path), cols, rows, added,
                          len(extra) * TS * TS))

    tiles = base + extra
    data = lz77_compress(b"".join(bytes(t) for t in tiles))
    if len(data) > 0xFFFF:
        sys.exit("%s would need %d bytes, more than the 16-bit size argument"
                 % (args.tileset, len(data)))

    os.makedirs(os.path.dirname(os.path.abspath(args.tileset)), exist_ok=True)
    with open(args.tileset, "wb") as f:
        f.write(data)

    out = bytearray()
    for value in palette:
        out.append(value & 0xFF)
        out.append((value >> 8) & 0xFF)
    with open(args.palette, "wb") as f:
        f.write(out)

    print("%s -> %d base tiles, %d merged, %d colors"
          % (os.path.basename(args.base_tileset), len(base), len(tiles), len(out) // 2))
    for line in reports:
        print("  " + line)


if __name__ == "__main__":
    main()
